import React from 'react';
import './App.css';

const Footer = () => {
  return (
    <footer className="reveal">
      <p>© 2025 The Freelance Marketplace</p>
      <a href="/about">About</a>
      <a href="/terms">Terms</a>
      <a href="/contact">Contact</a>
      <a href="/privacy">Privacy</a>
    </footer>
  );
};

export default Footer;
